function validate([balls]) {
  if (!Array.isArray(balls) || balls.length < 1 || balls.length > 8) return 'balls needs 1 to 8 colors.';
  if (balls.some(b => !Number.isInteger(b) || b < 1 || b > 6)) return 'Each color has 1 to 6 balls.';
  if (balls.reduce((a, b) => a + b, 0) % 2 !== 0) return 'The total number of balls must be even.';
  return null;
}

