function getProbability(balls) {
  const choose = (n, r) => {
    let result = 1;
    for (let i = 1; i <= r; i++) result = result * (n - r + i) / i;
    return result;
  };
  const total = balls.reduce((sum, count) => sum + count, 0);
  const half = total / 2;
  const k = balls.length;
  const table = () => Array.from({ length: half + 1 }, () => new Array(2 * k + 1).fill(0));

  let ways = table();
  ways[0][k] = 1;
  for (const count of balls) {
    const next = table();
    for (let taken = 0; taken <= half; taken++) {
      for (let diff = 0; diff <= 2 * k; diff++) {
        if (ways[taken][diff] === 0) continue;
        for (let first = 0; first <= count && taken + first <= half; first++) {
          const shift = first === 0 ? -1 : first === count ? 1 : 0;
          next[taken + first][diff + shift] += ways[taken][diff] * choose(count, first);
        }
      }
    }
    ways = next;
  }
  return ways[half][k] / choose(total, half);
}

