function getProbability(balls) {
  // Label every ball, try every set of half of them for the first box, and compare the colour counts.
  const colors = [];
  balls.forEach((count, color) => { for (let i = 0; i < count; i++) colors.push(color); });
  const half = colors.length / 2;
  const inFirst = new Array(colors.length).fill(false);
  let good = 0;
  let all = 0;
  function pick(index, left) {
    if (left === 0) {
      const first = new Set();
      const second = new Set();
      colors.forEach((c, i) => (inFirst[i] ? first : second).add(c));
      all++;
      if (first.size === second.size) good++;
      return;
    }
    if (colors.length - index < left) return;
    inFirst[index] = true;
    pick(index + 1, left - 1);
    inFirst[index] = false;
    pick(index + 1, left);
  }
  pick(0, half);
  return good / all;
}

