function generate(rand, size) {
  const large = size === 'large';
  for (;;) {
    const k = large ? 6 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 5);
    const top = large ? 6 : 4;
    const balls = Array.from({ length: k }, () => 1 + Math.floor(rand() * top));
    const total = balls.reduce((a, b) => a + b, 0);
    if (total % 2 === 0 && (large || total <= 14)) return [balls];
  }
}
